using System;using System.IO;using System.Collections.Generic;
class Offline70TypedEnemyDropsFG171 {
 internal static List<Offline70QuestDropFG> Plan(Offline70QuestCatalogFG catalog,Offline70ProgressionStateFG state,int enemy,int enemyType,int dungeon,int difficulty,string receipt){return Plan(catalog,state,enemy,enemyType,dungeon,difficulty,Offline70QuestDropsFG.StableDraws(receipt));}
 internal static List<Offline70QuestDropFG> Plan(Offline70QuestCatalogFG catalog,Offline70ProgressionStateFG state,int enemy,int enemyType,int dungeon,int difficulty,Func<int,int> random){
  if(catalog==null||state==null||random==null||enemy<=0||enemyType!=1&&enemyType!=2||dungeon<=0||difficulty<0||difficulty>3)throw new InvalidDataException("Typed quest drop profile");List<Offline70QuestDropFG> result=new List<Offline70QuestDropFG>();Dictionary<int,uint> counts=new Dictionary<int,uint>();foreach(Offline70ItemCountFG item in state.Items)counts.Add(item.Id,item.Quantity);
  foreach(Offline70QuestActiveFG active in state.Active){Offline70QuestDefinitionFG q=catalog.Get(active.Id);int[] rows=q.EnemyDropsFG171;if(rows==null||rows.Length%8!=0)throw new InvalidDataException("Original enemy reward item row width");List<int> candidates=new List<int>();for(int i=0;i<rows.Length;i+=8){if(rows[i]<=0||rows[i+1]!=1&&rows[i+1]!=2||rows[i+2]< -1||rows[i+3]< -1||rows[i+3]>3||rows[i+4]<=2||rows[i+5]<0||rows[i+5]>1000||rows[i+6]<0||rows[i+6]>100||rows[i+7]< -1)throw new InvalidDataException("Original enemy reward fields");if(rows[i]==enemy&&rows[i+1]==enemyType&&(rows[i+2]<0||rows[i+2]==dungeon)&&(rows[i+3]<0||rows[i+3]==difficulty))candidates.Add(i);}
   while(candidates.Count>0){int selected=random(candidates.Count);if(selected<0||selected>=candidates.Count)throw new InvalidDataException("Typed candidate draw");int i=candidates[selected],item=rows[i+4],chance=rows[i+6],maximum=rows[i+7];uint quantity=0;for(int n=0;n<rows[i+5];n++){int roll=random(100);if(roll<0||roll>=100)throw new InvalidDataException("Typed chance draw");if(roll<chance)quantity++;}if(quantity==0)break;uint current;counts.TryGetValue(item,out current);if(maximum>=0&&current>=(uint)maximum){candidates.RemoveAt(selected);continue;}if(maximum>=0)quantity=Math.Min(quantity,(uint)maximum-current);if(quantity==0)continue;counts[item]=checked(current+quantity);result.Add(new Offline70QuestDropFG{QuestId=q.Id,ItemId=item,Quantity=quantity,Chance=chance,MaximumCount=maximum});break;}
  }return result;
 }
